#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    int minOperationsAlternatingPrime(std::vector<int>& nums) {
        int MAX_V = 200000;
        std::vector<bool> isPrime(MAX_V + 1, true);
        isPrime[0] = isPrime[1] = false;
        for (int i = 2; i * i <= MAX_V; ++i) {
            if (isPrime[i]) {
                for (int j = i * i; j <= MAX_V; j += i) isPrime[j] = false;
            }
        }
        std::vector<int> primes;
        for (int i = 2; i <= MAX_V; ++i) if (isPrime[i]) primes.push_back(i);

        auto costToPrime = [&](int x) {
            auto it = std::lower_bound(primes.begin(), primes.end(), x);
            int best = std::abs(x - *it);
            if (it != primes.begin()) best = std::min(best, std::abs(x - *(it - 1)));
            return best;
        };

        long long cost0 = 0, cost1 = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            int cp = costToPrime(nums[i]);
            int cnp = isPrime[nums[i]] ? 1 : 0;
            if (i % 2 == 0) {
                cost0 += cp;
                cost1 += cnp;
            } else {
                cost0 += cnp;
                cost1 += cp;
            }
        }
        return std::min(cost0, cost1);
    }
};

import java.util.*;

class Solution {
    public int minOperationsAlternatingPrime(int[] nums) {
        int MAX_V = 200000;
        boolean[] isPrime = new boolean[MAX_V + 1];
        Arrays.fill(isPrime, true);
        isPrime[0] = isPrime[1] = false;
        for (int i = 2; i * i <= MAX_V; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= MAX_V; j += i) isPrime[j] = false;
            }
        }
        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i <= MAX_V; i++) if (isPrime[i]) primes.add(i);

        long cost0 = 0, cost1 = 0;
        for (int i = 0; i < nums.length; i++) {
            int idx = Collections.binarySearch(primes, nums[i]);
            int cp;
            if (idx >= 0) cp = 0;
            else {
                int ins = -(idx + 1);
                cp = Math.abs(nums[i] - primes.get(ins));
                if (ins > 0) cp = Math.min(cp, Math.abs(nums[i] - primes.get(ins - 1)));
            }
            int cnp = isPrime[nums[i]] ? 1 : 0;
            if (i % 2 == 0) {
                cost0 += cp;
                cost1 += cnp;
            } else {
                cost0 += cnp;
                cost1 += cp;
            }
        }
        return (int) Math.min(cost0, cost1);
    }
}

